// AI-generated load-pattern runner — closes proposal gap §10.3.
//
// Proposal §10.3: "AI-generated load patterns — Gemini synthesises traffic
// shapes (flash-sale spike, slow-leak DDoS, mixed-currency surge) used to
// drive k6 scenarios; tests the architecture against patterns a hand-coded
// harness wouldn't invent."
//
// This script does NOT hardcode a rate. It reads the stages generated by
// `uv run python -m velocityfraud.load_pattern_generator` from
// perf/ai_load_patterns.json, and drives k6's ramping-arrival-rate executor
// through whichever named pattern is selected via -e PATTERN=<name>.
//
// Run (after generating the patterns file):
//   k6 run -e BASE_URL=http://localhost:8000 -e PATTERN=flash_sale_spike perf/k6-ai-patterns.js
//   k6 run -e BASE_URL=http://localhost:8000 -e PATTERN=slow_leak_ddos perf/k6-ai-patterns.js
//   k6 run -e BASE_URL=http://localhost:8000 -e PATTERN=mixed_currency_surge perf/k6-ai-patterns.js

import http from "k6/http";
import { check } from "k6";
import { SharedArray } from "k6/data";

const BASE_URL = __ENV.BASE_URL || "http://localhost:8000";
const PATTERN_NAME = __ENV.PATTERN || "flash_sale_spike";

// SharedArray so the (small) JSON file is parsed once, shared across VUs.
const patternsFile = new SharedArray("patterns", function () {
  return JSON.parse(open("./ai_load_patterns.json")).patterns;
});

const pattern = patternsFile.find((p) => p.name === PATTERN_NAME);
if (!pattern) {
  throw new Error(
    `Pattern '${PATTERN_NAME}' not found in ai_load_patterns.json. ` +
    `Run: uv run python -m velocityfraud.load_pattern_generator first.`
  );
}

// Translate the generated {duration_s, target_rate} stages directly into
// k6's ramping-arrival-rate stage format.
const k6Stages = pattern.stages.map((s) => ({
  duration: `${s.duration_s}s`,
  target: s.target_rate,
}));
const peakRate = Math.max(...pattern.stages.map((s) => s.target_rate));

export const options = {
  scenarios: {
    ai_pattern: {
      executor: "ramping-arrival-rate",
      startRate: pattern.stages[0].target_rate,
      timeUnit: "1s",
      preAllocatedVUs: Math.max(20, Math.ceil(peakRate * 0.5)),
      maxVUs: peakRate * 2,
      stages: k6Stages,
    },
  },
  thresholds: {
    http_req_failed: ["rate<0.01"],
  },
  summaryTrendStats: ["avg", "min", "med", "p(90)", "p(95)", "p(99)", "max"],
};

const TXNS = [
  { amount: 125.99, merchant_name: "W-MERCHANT-gmail.com",     mcc: "5411", merchant_country: "US", card_token: "card_a1" },
  { amount: 42.5,   merchant_name: "R-MERCHANT-yahoo.com",     mcc: "5812", merchant_country: "US", card_token: "card_b2" },
  { amount: 999.0,  merchant_name: "S-MERCHANT-anonymous.com", mcc: "5999", merchant_country: "00", card_token: "card_c3", geo_distance_km: 8500 },
  { amount: 15.75,  merchant_name: "C-MERCHANT-hotmail.com",   mcc: "5732", merchant_country: "GB", card_token: "card_d4" },
  { amount: 320.0,  merchant_name: "H-MERCHANT-outlook.com",   mcc: "7011", merchant_country: "FR", card_token: "card_e5" },
];

export default function () {
  const base = TXNS[Math.floor(Math.random() * TXNS.length)];
  const payload = JSON.stringify({
    event_id: `ai-${PATTERN_NAME}-${__VU}-${__ITER}`,
    amount: base.amount,
    amount_fx_normalised: base.amount,
    currency: "USD",
    merchant_name: base.merchant_name,
    mcc: base.mcc,
    merchant_country: base.merchant_country,
    card_token: base.card_token,
    geo_distance_km: base.geo_distance_km || 0,
  });

  const res = http.post(`${BASE_URL}/score`, payload, {
    headers: { "Content-Type": "application/json" },
    timeout: "10s",
  });

  check(res, {
    "status is 200": (r) => r.status === 200,
    "has a decision": (r) => {
      try { return ["ALLOW", "REVIEW", "BLOCK"].includes(r.json("decision")); }
      catch (e) { return false; }
    },
  });
}

export function handleSummary(data) {
  const m = data.metrics;
  const reqs = m.http_reqs ? m.http_reqs.values.count : 0;
  const failed = m.http_req_failed ? (m.http_req_failed.values.rate * 100).toFixed(2) : "n/a";
  const d = m.http_req_duration ? m.http_req_duration.values : {};
  const line = "-".repeat(60);
  const summary = [
    "", line,
    ` AI-generated load pattern: ${pattern.name}  (mode: ${pattern.mode})`,
    line,
    `  ${pattern.description}`,
    "",
    `  total requests : ${reqs}`,
    `  failed         : ${failed}%`,
    `  latency p95    : ${d["p(95)"] ? d["p(95)"].toFixed(2) : "n/a"} ms`,
    `  latency max    : ${d.max ? d.max.toFixed(2) : "n/a"} ms`,
    line, "",
  ].join("\n");
  return { stdout: summary };
}
